<script setup lang="ts">
import { useProject } from '@/composables/useProjects'
import RegisterForm from '@/components/project/governance/RegisterForm.vue'; import { useProjectRegisterItem } from '@/composables/useProjectGovernance'; import { safeReturnTo } from '@/utils/safeReturnTo'; const route = useRoute(); const router = useRouter(); const { t } = useI18n(); const id = computed(() => Number(route.params.id)); const itemId = computed(() => Number(route.params.registerId)); const item = useProjectRegisterItem(id, itemId); const returnTo = computed(() => safeReturnTo(route.query.returnTo, `/projects/${id.value}/register/${itemId.value}`, ['/projects']))
